from pathlib import Path

p=Path('hero-generations.html')
s=p.read_text(encoding='utf-8')

if 'gen-summary-v702' not in s:
    css='''\n/* gen-summary-v702 */\n.gen-card{display:flex;flex-direction:column;min-height:0}\n.gen-img{height:260px;min-height:260px}\n.gen-img img{width:100%;height:100%;max-height:none;object-fit:contain;object-position:center bottom;padding:8px 8px 0}\n.gen-info{display:flex;flex:1;flex-direction:column;padding:14px 15px 15px}\n.gen-info b{margin-top:auto;padding-top:10px}\n.gen-summary{display:grid;gap:9px;margin-top:12px}\n.gen-strip{display:flex;align-items:flex-start;gap:12px;padding:12px 14px;border:1px solid rgba(137,207,246,.13);border-radius:14px;background:linear-gradient(145deg,rgba(255,255,255,.042),rgba(255,255,255,.022))}\n.gen-strip b{flex:0 0 92px;color:#eaf7ff;font-size:12px}\n.gen-strip span{color:#9fbfd2;font-size:12px;line-height:1.45}\n@media(max-width:980px){.gen-img{height:240px;min-height:240px}}\n@media(max-width:640px){.gen-card{min-height:0}.gen-img{height:220px;min-height:220px}.gen-strip{display:block}.gen-strip b{display:block;margin-bottom:4px}}\n'''
    s=s.replace('</style>',css+'</style>',1)

notes={
1:[('Главное','Стартовое поколение: база для ранней Арены, первых сборов и развития города.'),('Для F2P','Молли и Зинман доступны проще; Джеронимо и Наталия требуют значительно больше вложений.'),('Куда смотреть','Джеронимо — атакующие сборы, Молли — контроль, Зинман — строительство.')],
2:[('Главное','Поколение усиливает специализацию: Флинт — пехота, Алонсо — контроль, Филли — поддержка и лечение.'),('Для F2P','Флинт обычно главный доступный приоритет поколения.'),('Куда смотреть','Флинт полезен в сборах и PvP, Алонсо — в контроле, Филли — в выживаемости.')],
3:[('Главное','Миа даёт атакующую вариативность, Логан держит фронт, Грег сочетает контроль и поддержку.'),('Для F2P','Миа обычно самый удобный ключевой герой поколения.'),('Куда смотреть','Миа — универсальный PvP, Логан — гарнизон, Грег — Арена и контроль.')],
4:[('Главное','Линн отвечает за стрелков и антиконтроль, Ахмос — за переднюю линию, Рейна — за атакующие сборы.'),('Для F2P','Линн через Колесо удачи обычно лучший старт поколения.'),('Куда смотреть','Рейна особенно сильна как участник сборов, Ахмос — в защите.')],
5:[('Главное','Гектор укрепляет переднюю линию, Нора даёт контроль, Гвен давит заднюю линию и атакующие сборы.'),('Для F2P','Гектор — главный доступный приоритет через Колесо удачи.'),('Куда смотреть','После Гектора выбор между Норой и Гвен зависит от роли аккаунта.')],
6:[('Главное','Рене усиливает копейщиков, У Мин держит фронт, Уэйн даёт критический урон стрелков.'),('Для F2P','Рене — главный доступный герой поколения через Колесо удачи.'),('Куда смотреть','У Мин хорош в гарнизоне, Уэйн — в Арене и атакующем PvP.')],
7:[('Главное','Бредли — массовый урон стрелков, Эдит — защитная пехота, Гордон — атакующие копейщики.'),('Для F2P','Бредли через Колесо удачи — основной доступный герой поколения.'),('Куда смотреть','Эдит сильна в гарнизоне, Гордон — в атакующих маршах и сборах.')],
8:[('Главное','Гатот — щиты и оборона, Хендрик — дебафф защиты, Соня — контроль и стабильный урон.'),('Для F2P','Гатот обычно самый доступный вход в 8 поколение.'),('Куда смотреть','Хендрик полезен атакующим сборам, Соня сильна на Арене.')],
9:[('Главное','Фред давит пехоту и снижает смертоносность, Магнус усиливает марш, Ксура работает через дебаффы и стрелков.'),('Для F2P','Фред — герой Колеса удачи и основной доступный приоритет поколения.'),('Куда смотреть','Магнус особенно полезен как участник сборов и на Медведе.')],
10:[('Главное','Бланшетт — сильный стрелок, Фрея — поддержка копейщиков, Грегори — защитная пехота.'),('Для F2P','Бланшетт через Колесо удачи — главный доступный герой поколения.'),('Куда смотреть','Фрея усиливает выживаемость, Грегори — гарнизон и долгие бои.')],
11:[('Главное','Элеонора укрепляет пехоту, Ллойд ослабляет врага, Руфус даёт атакующий профиль стрелков.'),('Для F2P','Элеонора через Колесо удачи — главный доступный герой поколения.'),('Куда смотреть','Ллойд полезен в PvP через снижение смертоносности, Руфус — в атакующих составах.')],
12:[('Главное','Хервор — живучая пехота, Кароль — универсальные копейщики, Лигея — стрелок с сильными дебаффами защиты.'),('Для F2P','Кароль доступна через Колесо удачи и обычно становится основным F2P-приоритетом поколения.'),('Куда смотреть','Хервор — гарнизон, Кароль — универсальный марш, Лигея — PvP и ослабление противника.')]
}

for n, rows in notes.items():
    marker=f'<section class="gen-block" id="gen-{n}">'
    start=s.find(marker)
    if start<0: continue
    end=s.find('</section>', start)
    if end<0: continue
    section=s[start:end]
    if 'class="gen-summary"' in section: continue
    bars=''.join(f'<div class="gen-strip"><b>{label}</b><span>{text}</span></div>' for label,text in rows)
    summary=f'<div class="gen-summary">{bars}</div>'
    s=s[:end]+summary+s[end:]

p.write_text(s,encoding='utf-8')
